private val NUMBER_PAIR = Regex("""(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)""")

// ---- The female figure: the same drawing, re-proportioned ----
// Worked out in the design's own units (140 wide, centre line at x = 100),
// then converted back to the grid.

private const val DESIGN_SCALE = 100f / 140f

/** Body width at each height compared with the male figure: narrower
 *  shoulders and waist, wider hips and thighs. */
private val FEMALE_WIDTH = listOf(
    0f to 1f, 75f to 0.93f, 95f to 0.88f, 130f to 0.88f, 160f to 0.84f, 180f to 0.84f,
    200f to 0.96f, 215f to 1.06f, 245f to 1.08f, 280f to 1.03f, 300f to 0.98f, 422f to 0.95f
)

/** How far from the centre line the arm starts at each height (999 = no arm there). */
private val ARM_FROM = listOf(
    0f to 999f, 92f to 999f, 96f to 36f, 160f to 34f, 175f to 30f, 195f to 35f,
    210f to 40f, 270f to 40f, 280f to 999f
)

private fun lerpTable(table: List<Pair<Float, Float>>, y: Float): Float {
    if (y <= table.first().first) return table.first().second
    for (i in 1 until table.size) {
        val (y1, w1) = table[i]
        val (y0, w0) = table[i - 1]
        if (y <= y1) return w0 + (w1 - w0) * (y - y0) / (y1 - y0)
    }
    return table.last().second
}

private fun femalePoint(gx: Float, gy: Float): Pair<Float, Float> {
    val x = gx / DESIGN_SCALE + 30f
    val y = gy / DESIGN_SCALE + 14f
    val dx = x - 100f
    val nx: Float
    val ny: Float
    if (y < 75f) {
        // A slightly smaller head.
        nx = 100f + dx * 0.93f
        ny = 20f + (y - 20f) * 0.95f
    } else {
        val armFrom = lerpTable(ARM_FROM, y)
        val width = lerpTable(FEMALE_WIDTH, y)
        val a = abs(dx)
        // The body narrows/widens; the arms get slimmer and follow the shoulders.
        val na = if (a <= armFrom) a * width else armFrom * width + (a - armFrom) * 0.86f
        nx = 100f + sign(dx) * na
        ny = y
    }
    return (nx - 30f) * DESIGN_SCALE to (ny - 14f) * DESIGN_SCALE
}

private fun femaleShape(d: String): String = NUMBER_PAIR.replace(d) { m ->
    val (x, y) = femalePoint(m.groupValues[1].toFloat(), m.groupValues[2].toFloat())
    "${"%.2f".format(Locale.US, x)},${"%.2f".format(Locale.US, y)}"
}

private class ParsedShape(val region: BodyRegion, val path: Path, val hit: android.graphics.Region)

/** How much finer than the drawing grid tap-testing works. */
private const val HIT_SCALE = 4f

private fun parsePath(raw: String, type: BodyType): Path =
    PathParser().parsePathString(if (type == BodyType.FEMALE) femaleShape(raw) else raw).toPath()

private fun parseShapes(shapes: List<Pair<BodyRegion, List<String>>>, type: BodyType): List<ParsedShape> =
    shapes.flatMap { (region, ds) ->
        ds.map { raw ->
            val path = parsePath(raw, type)
            val scaled = android.graphics.Path(path.asAndroidPath()).apply {
                transform(android.graphics.Matrix().apply { setScale(HIT_SCALE, HIT_SCALE) })
            }
            val clip = android.graphics.Region(0, 0, (100 * HIT_SCALE).toInt(), (FIG_H * HIT_SCALE).toInt())
            ParsedShape(region, path, android.graphics.Region().apply { setPath(scaled, clip) })
        }
    }

private val parsedCache = java.util.concurrent.ConcurrentHashMap<Pair<BodyView, BodyType>, List<ParsedShape>>()
private val silhouetteCache = java.util.concurrent.ConcurrentHashMap<Pair<BodyView, BodyType>, Path>()

private fun shapesFor(view: BodyView, type: BodyType): List<ParsedShape> =
    parsedCache.getOrPut(view to type) { parseShapes(if (view == BodyView.FRONT) FRONT_SHAPES else BACK_SHAPES, type) }

private fun silhouetteFor(view: BodyView, type: BodyType): Path =
    silhouetteCache.getOrPut(view to type) { parsePath(if (view == BodyView.FRONT) FRONT_SILHOUETTE else BACK_SILHOUETTE, type) }

/** The shape under a point on the drawing grid, if any (a near miss
 *  still counts, so small shapes are easy to hit). */
private fun regionAt(shapes: List<ParsedShape>, x: Float, y: Float): BodyRegion? {
    val px = (x * HIT_SCALE).toInt()
    val py = (y * HIT_SCALE).toInt()
    shapes.firstOrNull { it.region !in NEUTRAL_REGIONS && it.hit.contains(px, py) }?.let { return it.region }
    // Nothing exactly under the finger: the closest shape within ~4 units.
    val reach = (4 * HIT_SCALE).toInt()
    return shapes
        .filter { s ->
            val b = s.hit.bounds
            s.region !in NEUTRAL_REGIONS &&
                px in (b.left - reach)..(b.right + reach) && py in (b.top - reach)..(b.bottom + reach)
        }
        .minByOrNull { s ->
            val b = s.hit.bounds
            val dx = maxOf(b.left - px, 0, px - b.right)
            val dy = maxOf(b.top - py, 0, py - b.bottom)
            dx * dx + dy * dy
        }
        ?.region
}

// ---------------------------------------------------------------------------
// Drawing
// ---------------------------------------------------------------------------

/** Untrained / ready muscle plates - a step lighter than the body. */
private val BodyIdle = Color(0xFF303036)

/** The body itself. On a card that is already this colour, one step lighter. */
private fun silhouetteColor(background: Color): Color =
    if (background == AppSurfaceVariant) AppBorder else AppSurfaceVariant

/** Muscle plate colour at [level]: 0 = grey, then dim orange up to the full accent. */
private fun bodyFill(level: Float): Color =
    if (level <= 0f) BodyIdle else lerp(BodyIdle, AppAccent, 0.3f + 0.7f * level.coerceIn(0f, 1f))

/**
 * One figure. [level] gives each shape's shading (0..1); shapes in
 * [outlined] get a white outline; [onTap] (optional) makes it tappable.
 * [gapColor] is whatever the figure sits on (it picks the body colour).
 */
@Composable
fun BodyFigure(
    view: BodyView,
    level: (BodyRegion) -> Float,
    modifier: Modifier = Modifier,
    width: Dp = 100.dp,
    outlined: Set<BodyRegion> = emptySet(),
    type: BodyType = BodyFigureStore.type,
    gapColor: Color = AppBackground,
    onTap: ((BodyRegion) -> Unit)? = null
) {
    val shapes = shapesFor(view, type)
    val silhouette = silhouetteFor(view, type)
    val bodyColor = silhouetteColor(gapColor)
    val tap by rememberUpdatedState(onTap)
    val tapModifier = if (onTap == null) Modifier else Modifier.pointerInput(view, type) {
        detectTapGestures { offset: Offset ->
            val k = 100f / size.width
            regionAt(shapes, offset.x * k, offset.y * k)?.let { region -> tap?.invoke(region) }
        }
    }
    Canvas(modifier = modifier.size(width = width, height = width * BODY_ASPECT).then(tapModifier)) {
        val k = size.width / 100f
        scale(scale = k, pivot = Offset.Zero) {
            drawPath(silhouette, color = bodyColor)
            shapes.forEach { s ->
                val lvl = if (s.region in NEUTRAL_REGIONS) 0f else level(s.region)
                drawPath(s.path, color = bodyFill(lvl))
            }
            shapes.filter { it.region in outlined }.forEach { s ->
                drawPath(s.path, color = AppTextPrimary, style = Stroke(width = 1.2f))
            }
        }
    }
}

/** Front and back side by side, labelled, centred on the screen. */
@Composable
fun BodyMapPair(
