const val SEX_MALE = "MALE"
const val SEX_FEMALE = "FEMALE"
const val SEX_UNSPECIFIED = "UNSPECIFIED"

/** The figure a profile's sex means; null = not given (they pick one). */
fun figureForSex(sex: String?): BodyType? = when (sex?.trim()?.uppercase()) {
    SEX_MALE -> BodyType.MALE
    SEX_FEMALE -> BodyType.FEMALE
    else -> null
}

/** A card with a front figure and a label, selectable. */
@Composable
private fun FigureCard(type: BodyType, label: String, on: Boolean, figureWidth: Dp, onClick: () -> Unit, modifier: Modifier = Modifier) {
    Column(
        modifier = modifier
            .clip(RoundedCornerShape(18.dp))
            .background(if (on) AppSurfaceVariant else AppSurface)
            .border(width = 1.5.dp, color = if (on) AppAccent else AppBorder, shape = RoundedCornerShape(18.dp))
            .clickable(onClick = onClick)
            .padding(vertical = 14.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        BodyFigure(
            view = BodyView.FRONT,
            level = { 0f },
            width = figureWidth,
            type = type,
            gapColor = if (on) AppSurfaceVariant else AppSurface
        )
        Spacer(modifier = Modifier.height(10.dp))
