/**
 * Female / Male (each showing its figure), and "Prefer not to say" - which
 * then asks which figure to draw. Used in onboarding and Profile.
 */
@Composable
fun SexChooser(
    sex: String?,
    onSex: (String) -> Unit,
    figure: BodyType?,
    onFigure: (BodyType) -> Unit,
