            FigureCard(BodyType.FEMALE, "Female", sex == SEX_FEMALE, figureWidth, { onSex(SEX_FEMALE) }, Modifier.weight(1f))
            FigureCard(BodyType.MALE, "Male", sex == SEX_MALE, figureWidth, { onSex(SEX_MALE) }, Modifier.weight(1f))
