// Bitmap version - for home-screen widgets, which can't run Compose drawing
// ---------------------------------------------------------------------------

private val FRONT_ONLY = CHEST_PARTS + BICEPS_PARTS + QUAD_PARTS + setOf(BodyRegion.ABS, BodyRegion.FRONT_DELT, BodyRegion.ADDUCTORS)
private val BACK_ONLY = TRICEPS_PARTS + HAM_PARTS + GLUTE_PARTS + setOf(
    BodyRegion.UPPER_TRAPS, BodyRegion.MID_TRAPS, BodyRegion.UPPER_BACK, BodyRegion.LATS,
    BodyRegion.LOWER_BACK, BodyRegion.REAR_DELT
)

/** Front or back - whichever shows more of [regions] (a pull day shows the back). */
fun bestViewFor(regions: Set<BodyRegion>): BodyView =
    if (regions.count { it in BACK_ONLY } > regions.count { it in FRONT_ONLY }) BodyView.BACK else BodyView.FRONT

/** One figure drawn into a bitmap [widthPx] wide ([BODY_ASPECT] times as tall),
 *  in the figure the user picked. [gapColor] is the widget's background. */
fun bodyBitmap(view: BodyView, level: (BodyRegion) -> Float, widthPx: Int, gapColor: Color = AppSurface): android.graphics.Bitmap {
    val w = widthPx.coerceAtLeast(8)
    val bitmap = android.graphics.Bitmap.createBitmap(w, (w * BODY_ASPECT).toInt(), android.graphics.Bitmap.Config.ARGB_8888)
    val canvas = android.graphics.Canvas(bitmap)
    canvas.scale(w / 100f, w / 100f)
    val fill = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG)
    val type = BodyFigureStore.type
    fill.color = silhouetteColor(gapColor).toArgb()
    canvas.drawPath(silhouetteFor(view, type).asAndroidPath(), fill)
    shapesFor(view, type).forEach { s ->
        val lvl = if (s.region in NEUTRAL_REGIONS) 0f else level(s.region)
        fill.color = bodyFill(lvl).toArgb()
        canvas.drawPath(s.path.asAndroidPath(), fill)
    }
    return bitmap
}

/**
 * Accounts made before sex was asked in onboarding get asked once, in a
 * sheet on top of the app. "Later" hides it until the app is next opened.
 */
@Composable
fun SexPromptSheet(visible: Boolean, onLater: () -> Unit) {
    val context = LocalContext.current
    val scope = androidx.compose.runtime.rememberCoroutineScope()
    var sex by androidx.compose.runtime.remember { mutableStateOf<String?>(null) }
    var figure by androidx.compose.runtime.remember { mutableStateOf<BodyType?>(null) }
    var saving by androidx.compose.runtime.remember { mutableStateOf(false) }
    var error by androidx.compose.runtime.remember { mutableStateOf<String?>(null) }
    val canSave = sex != null && (sex != SEX_UNSPECIFIED || figure != null) && !saving

    AppBottomSheet(visible = visible, onDismissRequest = onLater) {
        Text("ONE QUICK QUESTION", style = MaterialTheme.typography.labelSmall, color = AppTextMuted)
        Spacer(modifier = Modifier.height(4.dp))
        Text("What's your sex?", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold, color = AppTextPrimary)
        Spacer(modifier = Modifier.height(4.dp))
        Text(
            "Men and women train and progress differently. It also sets your body map figure. You can change it in Profile.",
            style = MaterialTheme.typography.bodySmall,
            color = AppTextSecondary
        )
        Spacer(modifier = Modifier.height(16.dp))
        SexChooser(sex = sex, onSex = { sex = it }, figure = figure, onFigure = { figure = it }, figureWidth = 52.dp)
        error?.let {
            Spacer(modifier = Modifier.height(8.dp))
            Text(it, style = MaterialTheme.typography.bodySmall, color = AppTextSecondary)
        }
        Spacer(modifier = Modifier.height(16.dp))
        androidx.compose.material3.Button(
            onClick = {
                val picked = sex ?: return@Button
                saving = true
                error = null
                scope.launch {
                    try {
                        val updated = com.example.workoutlog_androidstudio.api.NetworkClient.workoutApi.updateProfile(
                            com.example.workoutlog_androidstudio.api.UpdateProfileRequest(sex = picked)
                        )
                        if (picked == SEX_UNSPECIFIED) figure?.let { BodyFigureStore.set(context, it) }
                        AppDataCache.replaceProfile(updated)
                        TrainLogWidgets.requestRefresh(context)
                    } catch (e: Exception) {
                        error = "Couldn't save. Check your connection and try again."
                    } finally {
                        saving = false
                    }
                }
            },
            enabled = canSave,
            modifier = Modifier.fillMaxWidth().height(52.dp),
            shape = RoundedCornerShape(14.dp),
            colors = androidx.compose.material3.ButtonDefaults.buttonColors(containerColor = AppAccent, contentColor = AppOnAccent)
        ) {
            Text(if (saving) "Saving…" else "Save", fontWeight = FontWeight.Bold)
        }
        androidx.compose.material3.TextButton(onClick = onLater, modifier = Modifier.fillMaxWidth()) {
            Text("Later", color = AppTextSecondary)
        }
    }
}
